const assert=require('node:assert/strict'),fs=require('node:fs');
const {chromium,webkit}=require('playwright');
const engine=process.env.OVERVIEW_BROWSER||'chromium',base=process.env.OVERVIEW_URL||'http://127.0.0.1:8765/kaopu-human-overview/',out=process.env.OVERVIEW_QA_DIR||'combined';fs.mkdirSync(out,{recursive:true});
const expected='55467d5e5fef904ca9999231fde71a720ae411bcd8cb1f581de4f36cf84618b1',topology='e8526431b9b24bec71d8161ed409794a8398ffc68ad25800abb27e0fc09644de';
const cases=[{name:'common',path:'../kaopu-unified-human-workbench/'},{name:'skin',path:'../kaopu-skin-workbench/'}],sizes=[{name:'wide',width:2048,height:1040},{name:'desktop',width:1440,height:900}];
let browser,ctx,page;const report={engine,base,rows:[],requests:[],errors:[],passed:false,desktopOnly:true};const save=()=>fs.writeFileSync(`${out}/combined-neck-${engine}.json`,JSON.stringify(report,null,2));
(async()=>{
 browser=await({chromium,webkit})[engine].launch(engine==='webkit'?{headless:true}:{headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']});ctx=await browser.newContext({viewport:sizes[0]});page=await ctx.newPage();await ctx.tracing.start({screenshots:true,snapshots:true});page.on('pageerror',e=>report.errors.push({url:page.url(),message:e.message}));page.on('response',r=>{if(/neck=20261007-r1|neck-surface/.test(r.url()))report.requests.push({url:r.url(),status:r.status()})});
 for(const c of cases){await page.setViewportSize(sizes[0]);await page.goto(new URL(c.path,base).href,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>{const d=window.unifiedWorkbench?.diagnostics();return d?.ready&&!d.busy&&!d.lost&&d.neckSurfaceVertices===1116},null,{timeout:180000});
  assert.equal(await page.locator('script[src="src/app.js?neck=20261007-r1"]').count(),1);assert.equal(await page.locator('[data-wb-back]').getAttribute('href'),'../kaopu-human-overview/');
  const fingerprint=await page.evaluate(async()=>{const r=await fetch('./assets/adapter-fingerprint.json?neck=20261007-r1');if(!r.ok)throw Error('fingerprint HTTP '+r.status);return r.json()});assert.equal(fingerprint.id,expected);
  for(const size of sizes){await page.setViewportSize(size);await page.locator('[data-view="face"]').click();const range=page.locator('#weight');await range.scrollIntoViewIfNeeded();await range.focus();const before=await page.evaluate(()=>unifiedWorkbench.diagnostics().revision);await range.press('ArrowRight');await page.waitForFunction(r=>unifiedWorkbench.diagnostics().revision>r,before);
   const proof=await page.evaluate(()=>{const box=s=>{const r=document.querySelector(s).getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom}};return{diagnostics:unifiedWorkbench.diagnostics(),pixels:unifiedWorkbench.pixelAudit(),stage:box('#stage'),control:box('#weight'),panel:box('.wb-controls'),outerScroll:scrollY,view:{width:innerWidth,height:innerHeight}}});assert.equal(proof.diagnostics.vertices,25417);assert.equal(proof.diagnostics.topologySha256,topology);assert.equal(proof.diagnostics.neckSurfaceVertices,1116);assert(proof.diagnostics.neckSurfaceMaxMM>0&&Number.isFinite(proof.diagnostics.neckSurfaceMaxMM));assert(proof.pixels.colors>20);assert.equal(proof.pixels.error,0);assert(proof.stage.width>size.width*.6&&proof.stage.bottom<=size.height+1);assert(proof.control.y>=0&&proof.control.bottom<=size.height);assert.equal(proof.outerScroll,0);report.rows.push({name:c.name,size:size.name,...proof});save();await page.screenshot({path:`${out}/combined-${c.name}-${size.name}-${engine}.png`});await range.press('ArrowLeft');}
  const [download]=await Promise.all([page.waitForEvent('download'),page.locator('#exportProfile').click()]);const filename=`${out}/combined-${c.name}-profile-${engine}.json`;await download.saveAs(filename);const profile=JSON.parse(fs.readFileSync(filename));assert.equal(profile.adapterFingerprint,expected);assert.equal(profile.topologySha256,topology);await page.locator('[data-wb-back]').click();await page.waitForURL(base,{waitUntil:'domcontentloaded'});assert.equal(ctx.pages().length,1);
 }
 assert.deepEqual(report.errors,[]);assert(report.requests.some(r=>r.url.includes('/src/app.js?neck=20261007-r1')&&r.status===200));assert(report.requests.some(r=>r.url.includes('neck-surface.bin.gz')&&r.status===200));assert(report.requests.every(r=>r.status===200));report.passed=true;report.version=browser.version();save();await ctx.tracing.stop({path:`${out}/combined-neck-trace-${engine}.zip`});await browser.close();
})().catch(async e=>{report.errors.push({message:e.stack||String(e),url:page?.url()});save();console.error(e);try{await page?.screenshot({path:`${out}/combined-failure-${engine}.png`});await ctx?.tracing.stop({path:`${out}/combined-neck-trace-${engine}.zip`})}catch{}await browser?.close();process.exit(1)});
